ruleToc.nextTocUrl:
class.showpage@ul@li.-3@a@href
<js>
let list = [];
const maxPageUrl = String(result[0]);
const baseMatch = maxPageUrl.match(/(.*)_/);
const pageMatch = maxPageUrl.match(/_(\d+)\//);

if (baseMatch && pageMatch) {
    const basePath = baseMatch[1];
    const maxPageNum = parseInt(pageMatch[1]);

    if (maxPageNum > 2) {
        for (let pageIndex = 2; pageIndex <= maxPageNum; pageIndex++) {
            list.push(`${basePath}_${pageIndex}/`);
        }
    }
}
list;
</js>

